import os, jwt, time
from datetime import datetime, timedelta, timezone
from typing import Optional

JWT_SECRET = os.environ.get('JWT_SECRET', 'change-me')
JWT_ALGO = 'HS256'
JWT_EXPIRE_HOURS = 24*7

def create_access_token(user_id: str, extras: Optional[dict] = None) -> str:
    payload = {'sub': user_id, 'iat': datetime.now(timezone.utc), 'exp': datetime.now(timezone.utc) + timedelta(hours=JWT_EXPIRE_HOURS)}
    if extras: payload.update(extras)
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGO)

def decode_token(token: str) -> dict:
    return jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGO])

