import os
from sqlmodel import create_engine, Session

_engine = None

def get_engine():
    global _engine
    if _engine is None:
        _engine = create_engine(os.environ['DATABASE_URL'], pool_pre_ping=True)
    return _engine

def get_session():
    return Session(get_engine())
